import pandas as pd
from datetime import timedelta

def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = pd.NaT

    # Build initial snapshot dict keyed by user_id
    snapshot = {}
    for row in target_snapshot.itertuples(index=False):
        snapshot[row.user_id] = {
            "email": row.email,
            "status": row.status,
            "status_ts": row.status_ts,
        }

    # Filter events strictly after watermark
    if pd.isna(high_ts):
        events = cdc_events.copy()
    else:
        events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort by event_ts then event_seq for deterministic sequential application
    events = events.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    for ev in events.itertuples(index=False):
        uid = ev.user_id
        op = ev.op
        ts = ev.event_ts
        email = ev.email

        current = snapshot.get(uid)

        if op == "D":
            # soft delete: email preserved as of deletion (keep existing email if present)
            if current is not None:
                preserved_email = current["email"]
            else:
                # no existing record; use incoming email as fallback
                preserved_email = email
            snapshot[uid] = {
                "email": preserved_email,
                "status": "DELETED",
                "status_ts": ts,
            }
        elif op == "U":
            if current is None or current["status"] == "ACTIVE":
                snapshot[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            elif current["status"] == "DELETED":
                deletion_ts = current["status_ts"]
                threshold = deletion_ts + timedelta(days=7)
                if ts > threshold:
                    # resurrection
                    snapshot[uid] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                # else discard, no change
            # else unknown status, leave unchanged (defensive)

    # Build output dataframe
    rows = []
    for uid, data in snapshot.items():
        rows.append({
            "user_id": uid,
            "email": data["email"],
            "status": data["status"],
            "status_ts": data["status_ts"],
        })

    new_snapshot = pd.DataFrame(rows, columns=["user_id", "email", "status", "status_ts"])

    # Enforce dtypes consistent with schema
    if len(new_snapshot) > 0:
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype(str)
        new_snapshot["status"] = new_snapshot["status"].astype(str)
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"])
    else:
        new_snapshot = pd.DataFrame(columns=["user_id", "email", "status", "status_ts"])
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"])

    return {"new_snapshot": new_snapshot}
